// The programme of every party of the game on the ten themes (alliance-rules.js): complete and coherent where the collocazione is documented, and declared «non rilevata» (never an invented centrist
// position) where it is not. A programme generated by the game is a simulation, never a declaration of the real party: the page says so.
import assert from 'node:assert/strict';
import { readFile } from 'node:fs/promises';
import { startCareer } from './lib/long-run.mjs';
const build = (await readFile(new URL('../index.html', import.meta.url), 'utf8')).match(/main\.js\?v=([^"']+)/)?.[1];
const R = await import(new URL(`../src/core/alliance-rules.js?v=${build}`, import.meta.url).href);
const { store, db } = await startCareer({ seed: 'programmi', level: 'deputato', fast: true });
const world = store.getState().world;
assert.equal(R.THEMES.length, 10, 'dieci temi');
const documented = world.parties.filter(party => Number.isFinite(party.axis));
const missing = world.parties.filter(party => !Number.isFinite(party.axis));
assert.ok(documented.length >= 15, `i partiti del mondo hanno una collocazione documentata (${documented.length}/${world.parties.length})`);
for (const party of documented) {
  const program = R.programOf(world, party);
  assert.equal(Object.keys(program).length, 10, `${party.label}: programma sui dieci temi`);
  for (const [theme, value] of Object.entries(program)) assert.ok(Number.isFinite(value) && value >= -3 && value <= 3, `${party.label} · ${theme}: posizione valida (${value})`);
  if (Math.abs(party.axis) >= 2) assert.ok(Object.values(program).some(value => Math.abs(value) >= 1.5), `${party.label}: un partito di estremo ha posizioni nette su qualche tema, non tutte intermedie`);
}
// coherence: the further right, the more closed on immigration and the more traditional on civil rights
const byAxis = [...documented].sort((a, b) => a.axis - b.axis);
const left = byAxis.slice(0, 3), right = byAxis.slice(-3);
const mean = (items, theme) => items.reduce((sum, party) => sum + R.positionOf(world, party, theme), 0) / items.length;
for (const theme of ['immigrazione', 'diritti', 'europa']) assert.ok(mean(right, theme) > mean(left, theme), `${theme}: la destra è più a destra della sinistra`);
// the parties without a documented collocazione: NOT a middle position on everything, but unknown on every theme
for (const party of missing) {
  const program = R.programOf(world, party);
  assert.ok(Object.values(program).every(value => value === null), `${party.label}: nessuna posizione inventata (${JSON.stringify(program)})`);
  const other = documented[0];
  const compared = R.compare(world, party, other);
  assert.equal(compared.missing, 10, 'tutti i temi sono «dato non disponibile»');
  assert.equal(compared.conflicts.length, 0); assert.equal(compared.agreements.length, 0); assert.equal(compared.hard.length, 0);
  assert.ok(compared.rows.every(row => row.level === 'non-rilevato' && row.aText === 'posizione non rilevata' || row.bText === 'posizione non rilevata'), 'ogni riga lo dice');
  // a position fixed by the player (a compromise) is a real one: the theme then counts
  const fixed = { ...world, programPositions: { [party.id]: { economia: 1 } } };
  assert.equal(R.positionOf(fixed, party, 'economia'), 1);
}
// every real party of the catalogue is covered (the ones the player can choose)
const catalogue = [...db.parties, ...db.politicalMovements];
const unclassified = catalogue.filter(item => !item.politicalPosition);
assert.ok(unclassified.length <= 1, `i partiti del catalogo senza collocazione documentata sono pochissimi e dichiarati (${unclassified.map(item => item.name ?? item.officialName).join(', ')})`);
console.log(`check-party-programs: ok (${documented.length} partiti con programma sui 10 temi, ${missing.length} non rilevato)`);
